public static int lowerBound(int[] arr, int target) {
    int low = 0;                          // start of the search area
    int high = arr.length;                // one past the last index

    while (low < high) {                  // keep searching while a range remains
        int mid = low + (high - low) / 2; // safe middle point

        if (arr[mid] < target) {          // too small, answer is to the right
            low = mid + 1;
        } else {                          // possible answer, search left
            high = mid;                   // keep mid in the search area
        }
    }
    return low;                           // lower bound index
}

